const f = $('1. 시작 (폼)').item.json;
const isEdit = !!(f.edit_instruction && f.base_image_url);
let content;
if (isEdit) {
  const category = f.edit_category || '기타';
  content = [
    { type: 'text', text: `이 이미지에서 ${category}만 다음과 같이 바꿔줘: ${f.edit_instruction}. 나머지 요소는 최대한 그대로 유지해줘.` },
    { type: 'image_url', image_url: { url: f.base_image_url } }
  ];
} else {
  content = `다음 설명에 맞는 브랜드 캐릭터 마스코트 이미지를 생성해줘. 정면을 바라보는 전신 포즈, 단색(흰색) 배경, 다른 요소 없이 캐릭터만. 설명: ${f.brand_description}`;
}
const body = { model: 'google/gemini-3.1-flash-image-preview', modalities: ['image', 'text'], messages: [{ role: 'user', content }] };
return [{ json: { requestBody: JSON.stringify(body) } }];

const data = items[0].json;
let dataUrl = '';
try {
  const msg = data.choices?.[0]?.message;
  if (msg?.images?.[0]?.image_url?.url) dataUrl = msg.images[0].image_url.url;
  else if (typeof msg?.content === 'string' && msg.content.startsWith('data:image')) dataUrl = msg.content;
} catch (e) {}
if (!dataUrl.startsWith('data:image')) throw new Error('OpenRouter 응답에서 이미지를 못 찾았어요: ' + JSON.stringify(data).slice(0, 500));
const match = dataUrl.match(/^data:(image\/[a-zA-Z0-9.+-]+);base64,(.+)$/);
const mimeType = match ? match[1] : 'image/png';
const base64Data = match ? match[2] : dataUrl.split(',')[1];
const buffer = Buffer.from(base64Data, 'base64');
const ext = (mimeType.split('/')[1] || 'png').replace('+xml', '');
const binaryData = await this.helpers.prepareBinaryData(buffer, `character.${ext}`, mimeType);
return [{ json: { mime_type: mimeType, ext }, binary: { character_image: binaryData } }];

const f = $('1. 시작 (폼)').item.json;
const brandId = 'brand_' + Date.now();
return [{ json: { brand_id: brandId, ext: $json.ext, mime_type: $json.mime_type, storage_path: `${brandId}.${$json.ext}` }, binary: items[0].binary }];

const f = $('1. 시작 (폼)').item.json;
const id = $('3d. 브랜드ID 발급').item.json;
const imageUrl = `${$vars.SUPABASE_URL}/storage/v1/object/public/brand-characters/${id.storage_path}`;
const body = { brand_id: id.brand_id, description: f.brand_description, image_url: imageUrl, example_script: null, updated_at: new Date().toISOString() };
return [{ json: { requestBody: JSON.stringify(body), brand_id: id.brand_id, image_url: imageUrl, example_script: null } }];

const row = items[0].json[0];
if (!row) throw new Error('brand_id에 해당하는 캐릭터를 못 찾았어요. 등록부터 다시 하거나 brand_id를 확인하세요.');
return [{ json: { brand_id: row.brand_id, image_url: row.image_url, example_script: row.example_script || null } }];

const target = Number($('1. 시작 (폼)').item.json.target_length_sec);
const segmentsNeeded = Math.max(0, Math.ceil((target - 10) / 4.5));
const totalSegments = segmentsNeeded + 1; // 1차 + extend 횟수
return [{ json: { ...items[0].json, target_length_sec: target, segments_needed_extend: segmentsNeeded, total_segments: totalSegments } }];

const f = $('1. 시작 (폼)').item.json;
const d = $json;
const attempt = d.script_attempt || 0;
const failReason = d.script_fail_reason || '';
const example = d.example_script || '(예시 없음, 자연스러운 홍보 톤으로 자유롭게)';
const rate = 4; // 초당 발화 글자수 가정
const maxChars = Math.round(f.target_length_sec * rate);
const keywords = (f.must_include_keywords || '').split(',').map(s => s.trim()).filter(Boolean);

let extra = '';
if (attempt > 0 && failReason) extra = `\n\n[이전 시도 문제점 — 반드시 고쳐서 다시 써줘]\n${failReason}`;
if (attempt > 0 && f.script_feedback) extra += `\n\n[사용자 수정 요청 — 톤/타깃/강조/금지어]\n${f.script_feedback}`;

const prompt = `너는 브랜드 홍보 짧은 영상의 나레이션 대본을 쓰는 카피라이터다.\n없는 사실을 지어내지 마라.\n${keywords.length ? `다음 키워드는 대본에 반드시 그대로 포함해라: ${keywords.join(', ')}\n` : ''}총 글자수는 ${maxChars}자 이내로, 실제 사람이 말하듯 자연스러운 구어체 문장으로 써라.\n출력은 나레이션 문장만, 다른 설명·따옴표·마크다운 없이 순수 텍스트로만 출력해라.\n\n[예시 대본 — 톤 참고용]\n${example}\n\n[주제]\n${f.topic}${extra}`;

const body = { model: 'openai/gpt-5', messages: [{ role: 'user', content: prompt }] };
return [{ json: { ...d, requestBody: JSON.stringify(body), script_attempt: attempt, max_chars: maxChars, must_include_keywords: keywords } }];

const prev = $('8a. 대본 생성 요청 만들기').item.json;
const data = items[0].json;
const narration = (data.choices?.[0]?.message?.content || '').trim();
const f = $('1. 시작 (폼)').item.json;

// 코드 검증 1: 사용자가 지정한 필수 키워드가 대본에 그대로 들어갔는지 대조
const keywords = prev.must_include_keywords || [];
const missingKeywords = keywords.filter(k => !narration.includes(k));

// 코드 검증 2: 글자수 ÷ 발화속도로 낭독 길이 추정, 목표 길이와 비교 (±20% 허용)
const rate = 4;
const estSec = narration.length / rate;
const diffRatio = Math.abs(estSec - f.target_length_sec) / f.target_length_sec;

const problems = [];
if (missingKeywords.length) problems.push(`필수 키워드(${missingKeywords.join(', ')})가 대본에 안 들어감`);
if (diffRatio > 0.2) problems.push(`예상 낭독 길이 ${estSec.toFixed(1)}초, 목표 ${f.target_length_sec}초와 차이가 큼 (글자수 조정 필요)`);

const passed = problems.length === 0;
return [{ json: { ...prev, narration, passed, script_fail_reason: problems.join(' / '), script_attempt: prev.script_attempt + 1 } }];

const d = $json;
const body = { brand_id: d.brand_id, example_script: d.narration, updated_at: new Date().toISOString() };
return [{ json: { ...d, requestBody: JSON.stringify(body) } }];

const d = $('9a. 예시 저장 레코드 만들기').item.json;
const total = d.total_segments;
// 1차 영상은 10초, 이후 Extend는 각 5초로 요청하므로 그 비율만큼 글자수를 배분 (균등 분배 X)
const durations = [10, ...Array(Math.max(0, total - 1)).fill(5)];
const sumDur = durations.reduce((a, b) => a + b, 0);
const sentences = d.narration.split(/(?<=[.!?。])\s+/).filter(s => s.trim());
const totalChars = sentences.reduce((a, s) => a + s.length, 0) || 1;

const segments = [];
let si = 0;
for (let i = 0; i < total; i++) {
  const budget = totalChars * (durations[i] / sumDur);
  const remainingSegments = total - i;
  const chunk = [];
  let used = 0;
  while (si < sentences.length) {
    const s = sentences[si];
    if (remainingSegments === 1) { chunk.push(s); si++; continue; } // 마지막 구간은 남은 거 다 담기
    if (used === 0 || used + s.length <= budget * 1.3) { chunk.push(s); used += s.length; si++; }
    else break;
  }
  segments.push({ index: i, narration_text: chunk.join(' ').trim() || sentences[sentences.length - 1] || d.narration, target_duration_s: durations[i] });
}
return [{ json: { ...d, segments } }];

const d = $json;
const i = d.tts_index || 0;
const seg = d.segments[i];
const body = {
  input: { text: seg.narration_text },
  voice: { languageCode: 'ko-KR', name: 'ko-KR-Neural2-A' },
  audioConfig: { audioEncoding: 'MP3' }
};
return [{ json: { ...d, tts_index: i, requestBody: JSON.stringify(body) } }];

const data = items[0].json;
const base64Data = data.audioContent;
if (!base64Data) throw new Error('Google TTS 응답에서 audioContent를 못 찾았어요: ' + JSON.stringify(data).slice(0, 300));
const buffer = Buffer.from(base64Data, 'base64');
const binaryData = await this.helpers.prepareBinaryData(buffer, 'narration.mp3', 'audio/mpeg');
return [{ json: {}, binary: { narration_audio: binaryData } }];

const d = $('11a. TTS 요청 만들기 (구간별)').item.json;
// 11b3가 업로드한 경로와 정확히 같은 규칙(brand_id_ttsIndex.mp3)으로 재계산
const audioUrl = `${$vars.SUPABASE_URL}/storage/v1/object/public/narration-audio/${d.brand_id}_${d.tts_index}.mp3`;
const segments = d.segments.map((s, idx) => idx === d.tts_index ? { ...s, audio_url: audioUrl } : s);
return [{ json: { ...d, segments, tts_index: d.tts_index + 1 } }];

const d = $json;
const segList = d.segments.map((s, i) => `구간${i}: ${s.narration_text}`).join('
');
const prompt = `아래는 짧은 홍보 영상의 나레이션을 시간 구간별로 나눈 것이다.
각 구간마다, 그 나레이션이 나올 때 화면에 어떤 장면이 나와야 하는지 영상 생성용 장면 묘사를 만들어라.
나레이션 문장을 그대로 옮기지 말고, 카메라/동작/표정 등 시각적 요소로 새로 써라 (영어로, 한 구간당 1문장).
출력은 반드시 아래 JSON 형식 그대로만 출력해라 (설명 없이):
{"video_prompts": ["구간0 장면 묘사", "구간1 장면 묘사", ...]}
구간 개수는 정확히 ${d.total_segments}개여야 한다.

[나레이션 구간]
${segList}`;
const body = { model: 'openai/gpt-5', messages: [{ role: 'user', content: prompt }] };
return [{ json: { ...d, requestBody: JSON.stringify(body) } }];

const d = $('12a. 구간별 영상 프롬프트 요청 만들기').item.json;
const raw = items[0].json.choices?.[0]?.message?.content || '{}';
let parsed;
try { parsed = JSON.parse(raw.replace(/^```json\s*|```$/g, '').trim()); } catch (e) { parsed = { video_prompts: [] }; }
const prompts = parsed.video_prompts || [];
const passed = prompts.length === d.total_segments;
const segments = d.segments.map((s, i) => ({ ...s, video_prompt: prompts[i] || s.narration_text }));
return [{ json: { ...d, segments, vp_passed: passed } }];

const f = $('1. 시작 (폼)').item.json;
const d = $json;
const seg0 = d.segments[0];
const attempt = d.video_attempt || 0;
let prompt = seg0.video_prompt;
let negativePrompt = 'blurry, low quality, distorted, extra limbs, watermark';
if (attempt > 0 && f.video_feedback_want) prompt += `. ${f.video_feedback_want}`;
if (attempt > 0 && f.video_feedback_avoid) negativePrompt += `, ${f.video_feedback_avoid}`;
const body = { model_name: 'kling-v2-6', image: d.image_url, prompt, negative_prompt: negativePrompt, duration: '10', mode: 'std' };
return [{ json: { ...d, requestBody: JSON.stringify(body), video_attempt: attempt } }];

const d = $('13a. 영상 생성(1차) 요청 만들기').item.json;
const taskId = items[0].json?.data?.task_id || items[0].json?.data?.id || '';
return [{ json: { ...d, current_task_id: String(taskId), extend_index: 1 } }];

const d = $('13c. task_id 추출').item.json;
const task = items[0].json?.data || items[0].json;
const status = task?.task_status || task?.status || '';
const videoUrl = task?.task_result?.videos?.[0]?.url || '';
return [{ json: { ...d, status, video_url: videoUrl } }];

const f = $('1. 시작 (폼)').item.json;
const d = $json;
const i = d.extend_index;
const seg = d.segments[i];
const attempt = d.extend_attempt || 0;
let prompt = seg.video_prompt;
let negativePrompt = 'blurry, low quality, distorted, extra limbs, watermark';
if (attempt > 0 && f.video_feedback_want) prompt += `. ${f.video_feedback_want}`;
if (attempt > 0 && f.video_feedback_avoid) negativePrompt += `, ${f.video_feedback_avoid}`;
const body = { task_id: d.current_task_id, prompt, negative_prompt: negativePrompt, duration: '5', mode: 'std' };
return [{ json: { ...d, requestBody: JSON.stringify(body) } }];

const d = $('14a. 이어붙이기 요청 만들기').item.json;
const taskId = items[0].json?.data?.task_id || items[0].json?.data?.id || '';
return [{ json: { ...d, current_task_id: String(taskId) } }];

const d = $('14c. task_id 갱신').item.json;
const task = items[0].json?.data || items[0].json;
const status = task?.task_status || task?.status || '';
const videoUrl = task?.task_result?.videos?.[0]?.url || '';
return [{ json: { ...d, status, video_url: videoUrl } }];

const d = $json;
const segs = d.segments.filter(s => s.audio_url).map(s => ({ audio_url: s.audio_url, target_duration_s: s.target_duration_s }));
const body = { video_url: d.video_url, segments: segs };
return [{ json: { ...d, requestBody: JSON.stringify(body) } }];

const d = $json;
const brandId = $('6. 반복 횟수 계산').item.json.brand_id;
return [{ json: { ...d, storage_path: `${brandId}_${Date.now()}.mp4` }, binary: items[0].binary }];
